/// @brief Enumeration for Wi-Fi Aware error code.
/// @since_tizen 9.0
abstract class wifi_aware_error_e {
  /// Successful
  static const int WIFI_AWARE_ERROR_NONE = 0;

  /// Operation not permitted(1)
  static const int WIFI_AWARE_ERROR_NOT_PERMITTED = -1;

  /// Out of memory(12)
  static const int WIFI_AWARE_ERROR_OUT_OF_MEMORY = -12;

  /// Permission denied(13)
  static const int WIFI_AWARE_ERROR_PERMISSION_DENIED = -13;

  /// Device or resource busy(16)
  static const int WIFI_AWARE_ERROR_RESOURCE_BUSY = -16;

  /// Invalid function parameter(22)
  static const int WIFI_AWARE_ERROR_INVALID_PARAMETER = -22;

  /// Invalid operation(38)
  static const int WIFI_AWARE_ERROR_INVALID_OPERATION = -38;

  /// Now in progress(115)
  static const int WIFI_AWARE_ERROR_NOW_IN_PROGRESS = -115;

  /// Not supported
  static const int WIFI_AWARE_ERROR_NOT_SUPPORTED = -1073741822;

  /// Not initialized
  static const int WIFI_AWARE_ERROR_NOT_INITIALIZED = -51445759;

  /// Already initialized
  static const int WIFI_AWARE_ERROR_ALREADY_INITIALIZED = -51445758;

  /// Already enabled
  static const int WIFI_AWARE_ERROR_ALREADY_ENABLED = -51445757;

  /// Operation failed
  static const int WIFI_AWARE_ERROR_OPERATION_FAILED = -51445756;

  /// Rejected by peer
  static const int WIFI_AWARE_ERROR_REJECTED_BY_PEER = -51445755;

  /// Wi-Fi Interface is down
  static const int WIFI_AWARE_ERROR_INTERFACE_DOWN = -51445754;
}

